namespace EncDotNet.Testing;

/// <summary>
/// Describes the shape of a synthetic S-57 cell generated by <see cref="SyntheticS57Cell"/>.
/// </summary>
/// <remarks>
/// The built-in profiles are calibrated against real NOAA cells: record counts, the
/// distribution of edge lengths, attributes per feature and spatial pointers per feature
/// follow the measured averages of the cell named in each profile's summary. Those were
/// earlier editions; NOAA has since re-schemed its coverage into smaller cells (edition 36
/// of US4MD81M is about 320 KB), so the larger profiles now stand for the bigger cells an
/// application may still meet rather than for a typical current one.
/// </remarks>
/// <param name="Name">The profile name, used in the generated data set name and in benchmark output.</param>
/// <param name="Seed">The seed for the generator; the same profile always yields the same bytes.</param>
/// <param name="IsolatedNodes">The number of isolated nodes (RCNM 110) holding a single SG2D position.</param>
/// <param name="SoundingNodes">The number of isolated nodes holding an SG3D sounding array.</param>
/// <param name="SoundingsPerNode">The number of soundings in each sounding node.</param>
/// <param name="ConnectedNodes">The number of connected nodes (RCNM 120).</param>
/// <param name="Edges">The number of edges (RCNM 130).</param>
/// <param name="MeanEdgePoints">The mean number of intermediate SG2D points per edge.</param>
/// <param name="MaxEdgePoints">The number of points in the single longest edge.</param>
/// <param name="PointFeatures">The number of point features.</param>
/// <param name="LineFeatures">The number of line features.</param>
/// <param name="AreaFeatures">The number of area features.</param>
public sealed record SyntheticCellProfile(
    string Name,
    int Seed,
    int IsolatedNodes,
    int SoundingNodes,
    int SoundingsPerNode,
    int ConnectedNodes,
    int Edges,
    double MeanEdgePoints,
    int MaxEdgePoints,
    int PointFeatures,
    int LineFeatures,
    int AreaFeatures)
{
    /// <summary>
    /// A harbour-scale cell shaped like an earlier edition of NOAA US5WA50M (about 400 KB).
    /// </summary>
    public static SyntheticCellProfile Harbour { get; } = new(
        Name: "Harbour",
        Seed: 5050,
        IsolatedNodes: 148,
        SoundingNodes: 4,
        SoundingsPerNode: 66,
        ConnectedNodes: 861,
        Edges: 1024,
        MeanEdgePoints: 12.8,
        MaxEdgePoints: 1084,
        PointFeatures: 163,
        LineFeatures: 389,
        AreaFeatures: 211);

    /// <summary>
    /// An approach-scale cell shaped like an earlier edition of NOAA US4MD81M (about 3.5 MB).
    /// </summary>
    public static SyntheticCellProfile Approach { get; } = new(
        Name: "Approach",
        Seed: 4081,
        IsolatedNodes: 1372,
        SoundingNodes: 52,
        SoundingsPerNode: 64,
        ConnectedNodes: 5747,
        Edges: 7490,
        MeanEdgePoints: 18.0,
        MaxEdgePoints: 2771,
        PointFeatures: 1813,
        LineFeatures: 3376,
        AreaFeatures: 2143);

    /// <summary>
    /// A cell four times the size of <see cref="Approach"/> whose longest edge holds
    /// 15 000 points, so its record exceeds the 99 999-byte leader limit (S-57 Part 3,
    /// Annex A.3) and is written with a record length of <c>00000</c>.
    /// </summary>
    /// <remarks>
    /// Real cells this large are rare, which is why this scenario is synthetic.
    /// </remarks>
    public static SyntheticCellProfile Large { get; } = new(
        Name: "Large",
        Seed: 9999,
        IsolatedNodes: 4 * 1372,
        SoundingNodes: 4 * 52,
        SoundingsPerNode: 64,
        ConnectedNodes: 4 * 5747,
        Edges: 4 * 7490,
        MeanEdgePoints: 18.0,
        MaxEdgePoints: 15_000,
        PointFeatures: 4 * 1813,
        LineFeatures: 4 * 3376,
        AreaFeatures: 4 * 2143);

    /// <summary>
    /// Returns a copy of this profile with every record count multiplied by <paramref name="factor"/>.
    /// </summary>
    /// <param name="factor">The multiplier for record counts.</param>
    /// <returns>The scaled profile.</returns>
    public SyntheticCellProfile Scale(int factor) => this with
    {
        Name = $"{Name}x{factor}",
        IsolatedNodes = IsolatedNodes * factor,
        SoundingNodes = SoundingNodes * factor,
        ConnectedNodes = ConnectedNodes * factor,
        Edges = Edges * factor,
        PointFeatures = PointFeatures * factor,
        LineFeatures = LineFeatures * factor,
        AreaFeatures = AreaFeatures * factor
    };

    /// <inheritdoc/>
    public override string ToString() => Name;
}
